  <SequenceProgressPanel defaultIdentity={defaultIdentity} key={repo.sequenceProgress?.id??repo.repoId} progress={repo.sequenceProgress} error={repo.sequenceError} plan={sequenceStepPlan} content={sequenceContent} onInspect={()=>void run(async()=>{const step=repo.sequenceProgress?.current;if(!step)return;setSequenceContent(null);setSequenceStepPlan(await api.replayPreview(repo,step.oid,step.kind,step.mainline));})} onRead={(id,conflict,side)=>void run(async()=>{const step=repo.sequenceProgress?.current;if(!step)return;setSequenceContent(await api.content(repo,id,{kind:'replayConflict',oid:step.oid,operation:step.kind,mainline:step.mainline,conflict,side}));})} disabled={busy||!!repo.writeBlock||repo.recoveryPending} onAction={action=>void mutate(action)}/>
  {repo.replayDraftError&&<div className="error-banner" role="alert"><span>{repo.replayDraftError}</span><button disabled={busy} onClick={()=>void mutate({kind:'abortReplay'})}>Archive damaged replay draft</button></div>}
  {repo.replayDraft&&<div className="error-banner" role="status"><span>Replay resolution in progress · {repo.replayDraft.source.slice(0,12)}</span>{repo.replayCompletionReady?<button disabled={busy} onClick={()=>void mutate({kind:'continueReplay',message:'',author:'',email:''})}>Finish completed replay</button>:<button disabled={busy} onClick={()=>void resumeReplay(repo)}>Resume replay</button>}<button disabled={busy} onClick={()=>void mutate({kind:'abortReplay'})}>Abort replay</button></div>}
